@@ -226,33 +226,6 @@ body {
 #folderTree {
   overflow-y: auto;

-  @media not (prefers-contrast) {
-    & {
-      position: relative;
-    }
-
-    &::before,
-    &::after {
-      display: block;
-      content: "";
-      top: 0;
-      left: 0;
-      width: 100%;
-      height: 4px;
-      pointer-events: none;
-    }
-
-    &::before {
-      position: sticky;
-      background-image: radial-gradient(farthest-side at 50% 0, rgba(0, 0, 0, .15), rgba(0, 0, 0, 0));
-    }
-
-    &::after {
-      position: absolute;
-      background-color: var(--sidebar-background-color, var(--foldertree-background));
-    }
-  }
